import { defineSlot } from '../Slot';

/**
 * Cells at the end of every invoice line-item row — the region where per-line actions (change this
 * line, remove this line) live. Declared once here; features fill it without the line-item table
 * listing what goes in it (CLAUDE.md rule 3). Its context is the line's id and current values plus
 * the invoice it belongs to (for cache invalidation on a write).
 */
export const LineItemRow = defineSlot<{
  invoiceId: number;
  lineItemId: number;
  description: string;
  qty: number;
  unitPrice: number;
}>('lineitem.row');
=== money.ts ===
// Shared presentational primitive: how money is rendered everywhere in the app. A monetary figure
// shows a dollar sign, thousands separators and two decimal places, like "$1,234.50" (CLAUDE.md:
// ui/ primitives are composed, never branched per feature). Every place that surfaces an amount, a
// total or an outstanding figure formats it through here, so they stay identical for free.
export function formatMoney(amount: number | string): string {
  return `$${Number(amount).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

